nodes = definition["nodes"]
budget = [20000]

def walk(node_id, prefix):
    budget[0] -= 1
    if budget[0] <= 0:
        raise RuntimeError("frontier walk exceeded its budget; graph is malformed")
    if node_id is None or node_id not in nodes:
        return None

    path = prefix + node_id
    if path not in done:
        return path

    node = nodes[node_id]
    output = (done[path].get("output") or {})
    kind = node["kind"]

    if kind == "end":
        return None

    if kind == "for_each":
        # The loop node itself resolved the item list and recorded how many
        # iterations there are; each iteration gets its own path segment.
        count = int(output.get("count", 0))
        for index in range(count):
            inner = walk(node.get("body"), "%s/%d/" % (path, index))
            if inner:
                return inner
        return walk(node.get("next"), prefix)

    if kind == "while":
        iterations = int(output.get("iterations", 0))
        for index in range(iterations):
            inner = walk(node.get("body"), "%s/%d/" % (path, index))
            if inner:
                return inner
        return walk(node.get("next"), prefix)

    if kind == "parallel":
        # Every branch is offered before any of them advances, which is what
        # lets the worker pool run them at the same time.
        pending = [walk(branch, prefix) for branch in node.get("branches", [])]
        ready = [p for p in pending if p]
        if ready:
            join = node.get("join", "all")
            if join == "all":
                return ready[0]
            finished = len(node.get("branches", [])) - len(ready)
            needed = 1 if join == "any" else int(node.get("n", 1))
            if finished < needed:
                return ready[0]
        return walk(node.get("next"), prefix)

    # Everything else follows the branch the node recorded when it ran.
    branch = output.get("branch")

    # A condition does not carry its onward edge under the branch name:
    # "then" lives inside the clause that matched. The clause is found by
    # the test the node recorded, so this is still a walk over facts and
    # not a re-evaluation.
    if kind == "condition" and branch == "then":
        clauses = node.get("when") or []
        for clause in clauses:
            if clause.get("if") == output.get("matched"):
                return walk(clause.get("then"), prefix)
        # A recorded match that names no clause we can find is a definition
        # that changed under a running execution. Stopping is the honest
        # answer; guessing a clause would run the wrong branch.
        return None

    if branch and node.get(branch):
        return walk(node[branch], prefix)
    if branch == "__end__":
        return None

    for field in ("next", "then", "on_approve"):
        if node.get(field):
            return walk(node[field], prefix)
    return None

return walk(definition["start"], "")

from soar.playbooks.template import render

def walk(value, position):
    if isinstance(value, str):
        return render(value, context, position)
    if isinstance(value, dict):
        return {key: walk(item, position) for key, item in value.items()}
    if isinstance(value, (list, tuple)):
        return [walk(item, position) for item in value]
    return value

return walk(inputs or {}, "json")

from soar.approvals.engine import request_approval
from soar.approvals.policy import default_policies, evaluate
from soar.execution.dispatch import raise_alert
from soar.platform.ids import new_id
from soar.playbooks.template import lookup, render

import json

kind = node["kind"]
output = {}
spawn = None

if kind == "start":
    output = {"branch": "next"}

elif kind == "end":
    output = {"branch": "__end__", "outcome": node.get("outcome", "succeeded")}

elif kind == "condition":
    output = {"branch": "else"}
    for clause in node.get("when", []):
        if evaluate_expression(clause.get("if", ""), context):
            output = {"branch": "then", "matched": clause.get("if")}
            break

elif kind == "format":
    # The same resolver every template in the platform goes through, so
    # html escapes and a hostname carrying a script tag renders as text
    # in whatever it ends up inside.
    shape = node.get("format", "html")
    rendered = render(node.get("template", ""), context,
                      "html" if shape == "html" else "text")
    output = {"rendered": rendered, "format": shape,
              "length": len(rendered)}

elif kind == "switch":
    subject = render(node.get("subject", ""), context, "text")
    cases = node.get("cases", {})
    output = {"branch": "case" if subject in cases else "default",
              "subject": subject}

elif kind == "for_each":
    items = lookup(str(node.get("items", "")).strip("{} "), context) or []
    limit = int(node.get("max_iterations", 100))
    if len(items) > limit:
        # Truncation is recorded, never silent. A loop that quietly processed
        # the first 100 of 4000 indicators is a wrong answer that looks right.
        raise_alert(db, org_id, "loop_truncated", {
            "execution_id": execution["id"], "node": node.get("id"),
            "items": len(items), "limit": limit,
        })
    output = {"count": min(len(items), limit), "total": len(items),
              "truncated": len(items) > limit, "branch": "body"}

elif kind == "while":
    output = {"iterations": 0, "branch": "next"}

elif kind == "parallel":
    output = {"branches": len(node.get("branches", [])), "branch": "branches"}

elif kind == "set_var":
    value = render(str(node.get("value", "")), context, "json")
    db.execute(
        "UPDATE execution SET variables = variables || %s WHERE id = %s",
        [json.dumps({node["name"]: value}, default=str), execution["id"]],
        org_id,
    )
    output = {"branch": "next", node["name"]: value}

elif kind == "transform":
    output = dict(render_inputs(node.get("inputs", {}), context))
    output["branch"] = "next"

elif kind == "delay":
    # A durable wake, not a held thread: the row carries the time and the
    # scheduler picks it up. A waiting playbook costs nothing and survives a
    # restart.
    db.execute(
        "UPDATE execution_step SET status = 'pending', "
        "finished_at = now() + (%s || ' seconds')::interval WHERE id = %s",
        [str(int(node.get("seconds", 60))), step_id], org_id,
    )
    return {"status": "waiting", "enqueued": 0, "wake_in_s": node.get("seconds")}

elif kind == "approval":
    decision = evaluate(default_policies(), {
        "action_key": node.get("action_key"),
        "risk_level": node.get("risk_level", "high"),
        "severity": (context.get("incident") or {}).get("severity"),
        "initiator_kind": execution.get("initiator_kind"),
        "playbook": execution.get("playbook_id"),
    })
    if decision["effect"] == "deny":
        raise PermissionError("policy %r denies %s"
                              % (decision["name"], node.get("action_key")))
    if decision["effect"] == "allow":
        output = {"branch": "on_approve", "auto_approved": True,
                  "policy": decision["name"]}
    else:
        approval_id = request_approval(db, org_id, decision, {
            "execution_id": execution["id"], "step_id": step_id,
            "incident_id": execution.get("incident_id"),
            "requested_by_kind": "playbook",
            "requested_by_id": execution.get("playbook_id"),
            "action_key": node.get("action_key"),
            "action_summary": render(node.get("summary", ""), context, "text"),
            "risk_level": node.get("risk_level", "high"),
            "payload": render_inputs(node.get("inputs", {}), context),
        })
        return {"status": "waiting_approval", "enqueued": 0,
                "approval_id": approval_id}

elif kind == "task":
    rendered = render_inputs(node.get("inputs", {}), context)
    db.execute(
        "INSERT INTO task (id, org_id, incident_id, title, description, "
        "assignee_role, playbook_step_id) VALUES (%s,%s,%s,%s,%s,%s,%s)",
        [new_id("task"), org_id, execution.get("incident_id"),
         rendered.get("title", "Task from playbook"),
         rendered.get("detail"), rendered.get("assignee_role"), step_id],
        org_id,
    )
    output = {"branch": "next", "created": True}

elif kind == "sub_playbook":
    # Described, not started. The engine owns admission - depth caps, dedupe
    # and the published-version check all live there, and duplicating any of
    # them here would be a second way to start an execution.
    spawn = {"playbook": node.get("playbook"),
             "inputs": render_inputs(node.get("inputs", {}), context)}
    output = {"branch": "next", "sub_playbook": node.get("playbook")}

else:
    output = {"branch": "next"}

db.execute(
    "UPDATE execution_step SET status = 'succeeded', output = %s, "
    "started_at = coalesce(started_at, now()), finished_at = now() WHERE id = %s",
    [json.dumps(output, default=str), step_id], org_id,
)

# The node decided; the engine acts on it. Returning rather than calling
# advance() keeps the dependency one-way and means this function can be
# tested without an engine at all.
return {"status": "advanced", "output": output, "spawn": spawn}

import re

OPS = {
    "==": lambda a, b: a == b,
    "!=": lambda a, b: a != b,
    ">=": lambda a, b: as_number(a) >= as_number(b),
    "<=": lambda a, b: as_number(a) <= as_number(b),
    ">": lambda a, b: as_number(a) > as_number(b),
    "<": lambda a, b: as_number(a) < as_number(b),
    " in ": lambda a, b: a in (b or []),
    " not_in ": lambda a, b: a not in (b or []),
    " contains ": lambda a, b: b in (a or []),
}

text = (expression or "").strip()
if not text:
    return False

for joiner, combine in ((" and ", all), (" or ", any)):
    if joiner in text:
        return combine(evaluate_expression(part, context) for part in text.split(joiner))

if text.startswith("not "):
    return not evaluate_expression(text[4:], context)

for symbol, test in OPS.items():
    if symbol not in text:
        continue
    left, _, right = text.partition(symbol)
    try:
        return bool(test(resolve_token(left, context), resolve_token(right, context)))
    except (TypeError, ValueError):
        return False

# A bare path is truthy if it resolves to something.
return bool(resolve_token(text, context))

